import type { ReactNode } from "react";

export const actionButtonVariantValues = ["primary", "secondary", "ghost", "danger"] as const;
export const actionButtonSizeValues = ["sm", "md", "lg"] as const;

/** One button that handles the permission check, an optional confirmation, the pending state and a result message for an action. It does not fetch data, show toasts, cache or route: you pass the function that does the work. */
export interface ActionButtonSpecProps {
  /**
   * Button label. Name the action, such as Delete user.
   */
  children: ReactNode;
  /**
   * The work. May be async; its resolved value goes to onSuccess and a throw or rejection goes to onError.
   */
  onAction: () => void | Promise<unknown>;
  /**
   * What the person may do: allow (default), disabled (shown, focusable, says why) or hidden (renders nothing). Use { state: "disabled", reason } to explain. The server must check again.
   */
  permission?: import("../utils/permissions").PermissionValue;
  /**
   * Ask first. Opens an alert dialog (danger tone when the variant is danger); the confirm button runs onAction. confirmText makes the person type a word before it works.
   */
  confirm?: { title: string; description?: string; confirmLabel?: string; cancelLabel?: string; confirmText?: string };
  /**
   * Visual emphasis, same as Button.
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "ghost" | "danger";
  /**
   * Height, padding and font size.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Icon shown before the label. Decorative, so the label must say what the button does.
   */
  icon?: ReactNode;
  /**
   * Announced politely to screen readers when the action succeeds. Show your own toast in onSuccess if you also want it on screen.
   */
  successMessage?: string;
  /**
   * Announced politely to screen readers when the action fails.
   */
  errorMessage?: string;
  /**
   * Called with the resolved value when the action succeeds.
   */
  onSuccess?: (result: unknown) => void;
  /**
   * Called with the error when the action throws or rejects.
   */
  onError?: (error: unknown) => void;
  /**
   * Called when the state moves between idle, pending, success and error.
   */
  onStateChange?: (state: import("../utils/state").ActionState) => void;
}

export const actionButtonDefaults = {
  variant: "primary",
  size: "md",
} as const;

export const actionButtonMeta = {
  "name": "ActionButton",
  "version": "0.1.0",
  "status": "experimental",
  "role": "button"
} as const;
